@startuml

class City {
  + name : string
  + inhabitants : int
}

class Attraction {
  + name : string
  + address : string
}

class GuidedTour {
  + duration : int
  + number : int
}

class Person {
  + name : string
}

class Visitor extends Person {}

class Guide extends Person {}

class Discount {
  + amount : float
}

City "1" -- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "1" -- "1" Guide
GuidedTour "0..*" -- "1..20" Visitor
Visitor "0..*" -- "0..*" GuidedTour : Discount
Discount "1" -- "1" Visitor
Discount "1" -- "1" GuidedTour

@enduml

